 // ==== Updates page ====
 function initUpdatesPage() {
   const updatesList = document.getElementById('updates-list');
   if (!updatesList) return;
   fetch('recent-tweaks.json')
     .then(r => r.json())
     .then(list => {
       // Take first 5 items (newest first)
       const recent = list.slice(0, 5);
       updatesList.innerHTML = '';
       recent.forEach(text => {
         const li = document.createElement('li');
         li.textContent = text;
         updatesList.appendChild(li);
       });
     })
     .catch(err => {
       console.error('Failed to load updates:', err);
       updatesList.textContent = 'Failed to load updates.';
     });
 }

 // ==== Changes page ====
 function initChangesPage() {
   const changesList = document.getElementById('changes-list');
   if (!changesList) return;

   fetch('log.json')
     .then(r => r.json())
     .then(log => {
       // Sort by timestamp descending (newest first)
       const sorted = [...log].sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
       changesList.innerHTML = '';

       sorted.forEach(tick => {
         const li = document.createElement('li');
         const dateStr = new Date(tick.timestamp).toISOString().replace('T', ' ').replace('Z', '');
         li.innerHTML = `<strong>${dateStr}</strong> — ${tick.changedPaths ? tick.changedPaths.join(', ') : 'No changes'}`;
         changesList.appendChild(li);
       });

       // Wire up copy/download buttons
       const copyBtn = document.getElementById('copy-changes-btn');
       const downloadBtn = document.getElementById('download-changes-btn');
       const copyMsg = document.getElementById('copy-changes-msg');
       const downloadMsg = document.getElementById('download-changes-msg');

       if (copyBtn) {
         copyBtn.addEventListener('click', () => {
           const json = JSON.stringify(sorted, null, 2);
           navigator.clipboard.writeText(json).then(() => {
             if (copyMsg) showMsg('copy-changes-msg', 'Changes copied as JSON!');
           }).catch(err => {
             console.error('Failed to copy:', err);
             if (copyMsg) showMsg('copy-changes-msg', 'Failed to copy changes');
           });
         });
       }

       if (downloadBtn) {
         downloadBtn.addEventListener('click', () => {
           const json = JSON.stringify(sorted, null, 2);
           const blob = new Blob([json], { type: 'application/json' });
           const url = URL.createObjectURL(blob);
           const a = document.createElement('a');
           a.href = url;
           a.download = 'changes.json';
           a.click();
           URL.revokeObjectURL(url);
           if (downloadMsg) showMsg('download-changes-msg', 'Changes downloaded!');
         });
       }
     })
     .catch(err => {
       console.error('Failed to load changes:', err);
       changesList.textContent = 'Failed to load changes.';
     });
 }

 // ==== Initialize on DOMContentLoaded ====
 document.addEventListener('DOMContentLoaded', () => {
   initLiveStatus();
   initUpdatesPage();
   initChangesPage();
 });

